using System.Collections.Concurrent;
using System.Net.Http.Headers;
using System.Net.Http.Json;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using PixelTart.SelectionApi.Contracts;
using RAWSelectionAssistant.Core.Models;
namespace RAWSelectionAssistant.Core.Services.OnlineSelection;

/// <summary>Explicitly configured loopback HTTP/HTTPS test adapter; no listener or implicit cloud service.</summary>
public sealed class HttpOnlineSelectionProvider : IHttpOnlineSelectionWorkflow, IDisposable
{
 private sealed record Access(Guid ProjectId,string PublicId,string OwnerToken,int Version,long Revision,string? Link=null,long AppliedRevision=0,DateTimeOffset? Expires=null);
 private readonly HttpClient client;private readonly string path;private readonly string ownerKey;private readonly ConcurrentDictionary<Guid,Access> access=new();private readonly SemaphoreSlim accessGate=new(1,1);
 private static readonly JsonSerializerOptions Json=new(JsonSerializerDefaults.Web){WriteIndented=true};private static readonly byte[] Entropy=Encoding.UTF8.GetBytes("Kitao/Selection/HttpV1Access");
 public HttpOnlineSelectionProvider(Uri endpoint,string accessPath,string createKey)
 {
  if(!endpoint.IsAbsoluteUri||endpoint.AbsolutePath!="/"||!string.IsNullOrEmpty(endpoint.UserInfo)||endpoint.Scheme!="https"&&!(endpoint.Scheme=="http"&&endpoint.IsLoopback)||!string.IsNullOrEmpty(endpoint.Query)||!string.IsNullOrEmpty(endpoint.Fragment))throw new ArgumentException("Use loopback HTTP or explicitly configured HTTPS.");
  if(endpoint.Scheme=="http"&&endpoint.IsLoopback)endpoint=new UriBuilder(endpoint){Host="127.0.0.1"}.Uri;
  client=new HttpClient(new HttpClientHandler{AllowAutoRedirect=false}){BaseAddress=endpoint,Timeout=TimeSpan.FromSeconds(20)};path=Path.GetFullPath(accessPath);ownerKey=createKey;
  if(File.Exists(path)){var bytes=ProtectedData.Unprotect(File.ReadAllBytes(path),Entropy,DataProtectionScope.CurrentUser);foreach(var a in JsonSerializer.Deserialize<Access[]>(bytes,Json)??throw new InvalidDataException("Invalid access store"))access[a.ProjectId]=a;}
 }
 public OnlineSelectionProviderKind Kind=>OnlineSelectionProviderKind.LocalDev;public bool IsConfigured=>true;public string DisplayName=>"HTTP 测试服务";
 public string? PublishedLink(Guid id)=>access.TryGetValue(id,out var a)&&a.Expires>DateTimeOffset.UtcNow?a.Link:null;public int? ExpectedSelectionVersion(Guid id)=>access.TryGetValue(id,out var a)?a.Version:null;
 static OnlineSelectionProviderResult<T> Failure<T>(string code,string message)=>OnlineSelectionProviderResult<T>.Failed(code,message);
 static OnlineSelectionProviderResult<T> Network<T>()=>Failure<T>("NetworkUnavailable","测试服务未连接；可使用同一项目/素材身份重试。");
 HttpRequestMessage Request(HttpMethod method,string url,string token){var r=new HttpRequestMessage(method,url);r.Headers.Authorization=new AuthenticationHeaderValue("Bearer",token);return r;}
 async Task<T> Parse<T>(HttpResponseMessage r,CancellationToken ct){using(r){if(r.IsSuccessStatusCode)return await r.Content.ReadFromJsonAsync<T>(Json,ct)??throw new InvalidDataException("Empty service response");var p=await r.Content.ReadFromJsonAsync<ApiProblem>(Json,ct);throw new ServiceException(p?.Code??"Http"+(int)r.StatusCode,p?.Message??"服务请求失败。");}}
 sealed class ServiceException(string code,string text):Exception(text){public string Code{get;}=code;}
 async Task Save(CancellationToken ct){await accessGate.WaitAsync(ct);try{Directory.CreateDirectory(Path.GetDirectoryName(path)!);var staging=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{var bytes=ProtectedData.Protect(JsonSerializer.SerializeToUtf8Bytes(access.Values.ToArray(),Json),Entropy,DataProtectionScope.CurrentUser);await File.WriteAllBytesAsync(staging,bytes,ct);File.Move(staging,path,true);}finally{if(File.Exists(staging))File.Delete(staging);}}finally{accessGate.Release();}}
 async Task<OnlineSelectionProviderResult<T>> Run<T>(Func<Task<T>> f,CancellationToken ct){try{return OnlineSelectionProviderResult<T>.Completed(await f());}catch(ServiceException e){return Failure<T>(e.Code,e.Message);}catch(Exception e)when(e is HttpRequestException or IOException or JsonException or TaskCanceledException){if(ct.IsCancellationRequested)throw new OperationCanceledException(ct);return Network<T>();}}
 private async Task EnsureProtocol(CancellationToken ct){using var response=await client.GetAsync("/health/ready",ct);if(!response.IsSuccessStatusCode)throw new ServiceException("ServiceUnavailable","测试服务尚未就绪。");using var json=JsonDocument.Parse(await response.Content.ReadAsStringAsync(ct));if(!json.RootElement.TryGetProperty("mode",out var mode)||mode.GetString()!="LocalDevHttpV1")throw new ServiceException("ServiceProtocolMismatch","服务不是本版测试API，未发送项目或照片。");}
 public Task<OnlineSelectionProviderResult<SelectionProject>> CreateProjectAsync(SelectionProject project,CancellationToken ct=default)=>Run(async()=>{
  await EnsureProtocol(ct);
  if(access.ContainsKey(project.Id)){var got=await GetProjectAsync(project.Id,ct);if(!got.Success)throw new ServiceException(got.ErrorCode!,got.Message);return got.Value! with{LocalSourceDirectory=project.LocalSourceDirectory,WorkflowProjectId=project.WorkflowProjectId};}
  using var r=new HttpRequestMessage(HttpMethod.Post,"/v1/selection-projects");r.Headers.TryAddWithoutValidation("X-Owner-Key",ownerKey);r.Headers.TryAddWithoutValidation("Idempotency-Key","project:"+project.Id.ToString("N"));r.Content=JsonContent.Create(new CreateSelectionProjectRequest(project.Name,project.ClientDisplayName,project.TargetCount,project.DeadlineUtc){ClientProjectId=project.Id},options:Json);
  var value=await Parse<LocalDevCreateProjectResponse>(await client.SendAsync(r,ct),ct);if(value.Project.Id!=project.Id||value.Project.PublicId.Length!=36)throw new ServiceException("ProjectIdentityMismatch","服务项目身份不匹配。");access[project.Id]=new(project.Id,value.Project.PublicId,value.DevAccessToken,value.Project.SelectionVersion,value.Project.Revision);await Save(ct);return Model(value.Project) with{LocalSourceDirectory=project.LocalSourceDirectory,WorkflowProjectId=project.WorkflowProjectId};},ct);
 public Task<OnlineSelectionProviderResult<SelectionProject>> UpdateProjectAsync(SelectionProject p,CancellationToken ct=default)=>Task.FromResult(Failure<SelectionProject>("UnsupportedUpdate","首版测试服务暂不支持编辑远端项目资料。"));
 public Task<OnlineSelectionProviderResult<SelectionProject>> GetProjectAsync(Guid id,CancellationToken ct=default)=>Run(async()=>{var a=AccessFor(id);using var r=Request(HttpMethod.Get,$"/v1/selection-projects/{id}",a.OwnerToken);var p=await Parse<SelectionProjectResponse>(await client.SendAsync(r,ct),ct);if(p.Id!=id)throw new ServiceException("ProjectIdentityMismatch","服务返回了其他项目。");access[id]=a with{Version=p.SelectionVersion,Revision=p.Revision};await Save(ct);return Model(p);},ct);
 public Task<OnlineSelectionProviderResult<SelectionAsset>> UploadAssetAsync(Guid id,SelectionAsset asset,Stream content,IProgress<SelectionUploadProgress>? progress=null,CancellationToken ct=default)=>Run(async()=>{var a=AccessFor(id);if(asset.ProjectId!=id||asset.Id==Guid.Empty||!content.CanSeek)throw new ServiceException("UploadIdentityInvalid","素材身份或流不可重试。");var start=content.Position;var sha=Convert.ToHexString(await SHA256.HashDataAsync(content,ct));content.Position=start;
  using var r=Request(HttpMethod.Post,$"/v1/selection-projects/{id}/assets/{asset.Id}/proxy",a.OwnerToken);r.Headers.TryAddWithoutValidation("X-Original-File-Name",Uri.EscapeDataString(Path.GetFileName(asset.OriginalFileName)));r.Headers.TryAddWithoutValidation("X-Content-SHA256",sha);r.Headers.TryAddWithoutValidation("Idempotency-Key",$"asset:{id:N}:{asset.Id:N}:{sha}");r.Content=new StreamContent(new BorrowedStream(content));r.Content.Headers.ContentType=new("image/jpeg");
  var got=await Parse<LocalDevAssetUploadResponse>(await client.SendAsync(r,ct),ct);if(got.ProjectId!=id||got.SelectionAssetId!=asset.Id||got.Status!="Ready"||got.UploadSha256!=sha)throw new ServiceException("AssetIdentityMismatch","上传确认身份无效。");access[id]=a with{Version=got.SelectionVersion,Revision=got.Revision};await Save(ct);progress?.Report(new(asset.Id,got.ProxyBytes,got.ProxyBytes));return asset with{Status=SelectionAssetStatus.Ready,CloudAssetId=asset.Id.ToString("N"),LastErrorCode=null,UpdatedAtUtc=DateTimeOffset.UtcNow};},ct);
 public Task<OnlineSelectionProviderResult<SelectionPublish>> PublishProjectAsync(Guid id,SelectionPublish publish,CancellationToken ct=default)=>Task.FromResult(Failure<SelectionPublish>("RuleRequired","HTTP 发布必须包含当前选片规则。"));
 public Task<OnlineSelectionProviderResult<SelectionPublish>> PublishWithRuleAsync(Guid id,SelectionPublish publish,SelectionRule rule,CancellationToken ct=default)=>Run(async()=>{var a=AccessFor(id);using var r=Request(HttpMethod.Post,$"/v1/selection-projects/{id}/publish",a.OwnerToken);r.Content=JsonContent.Create(new PublishWithRuleRequest(new(rule.TargetCount,rule.MinimumCount,rule.MaximumCount,rule.AllowExtraSelections,rule.ExtraSelectionPriceMinor,rule.AllowComments,rule.AllowFavorites,rule.AllowDownload,rule.ShowFileNames,rule.ApplyWatermark,rule.DeadlineUtc,rule.RequirePin,rule.LockAfterConfirmation),rule.AccessExpiresAtUtc),options:Json);var got=await Parse<PublishedLinkResponse>(await client.SendAsync(r,ct),ct);if(got.ProjectId!=id||got.PublicId!=a.PublicId||got.SelectionVersion!=a.Version||got.Revision<a.Revision||got.ExpiresAtUtc<=DateTimeOffset.UtcNow||!Uri.TryCreate(got.ProtectedUrl,UriKind.Absolute,out var link)||link.GetLeftPart(UriPartial.Authority)!=client.BaseAddress!.GetLeftPart(UriPartial.Authority)||!link.AbsolutePath.Equals("/s/"+got.PublicId,StringComparison.Ordinal)||!System.Text.RegularExpressions.Regex.IsMatch(link.Fragment,"^#token=[a-fA-F0-9]{64}$"))throw new ServiceException("PublishIdentityMismatch","服务签发链接无效。");access[id]=a with{Link=got.ProtectedUrl,Expires=got.ExpiresAtUtc,Version=got.SelectionVersion,Revision=got.Revision,PublicId=got.PublicId};await Save(ct);return publish with{PublicId=got.PublicId,ExpiresAtUtc=got.ExpiresAtUtc};},ct);
 public Task<OnlineSelectionProviderResult<SelectionProgress>> GetSelectionProgressAsync(Guid id,CancellationToken ct=default)=>Run(async()=>{var a=AccessFor(id);using var r=Request(HttpMethod.Get,$"/v1/selection-projects/{id}/progress",a.OwnerToken);var p=await Parse<SelectionProgressResponse>(await client.SendAsync(r,ct),ct);if(p.ProjectId!=id)throw new ServiceException("ProjectIdentityMismatch","结果项目无效。");return new SelectionProgress(id,p.Total,p.Ready,p.Selected,p.Favorites,p.Comments,0,p.LastActivityUtc);},ct);
 public Task<OnlineSelectionProviderResult<SelectionFinalResult>> GetFinalSelectionAsync(Guid id,CancellationToken ct=default)=>Run(async()=>{var a=AccessFor(id);using var r=Request(HttpMethod.Get,$"/v1/selection-projects/{id}/final-selection",a.OwnerToken);var p=await Parse<FinalSelectionSnapshotResponse>(await client.SendAsync(r,ct),ct);if(p.ProjectId!=id||p.SelectionVersion!=a.Version||p.Revision<a.AppliedRevision||!p.IsLocked||p.Items.Any(x=>x.SelectionProjectId!=id)||p.Items.Select(x=>x.ImageId).Distinct().Count()!=p.Items.Count)throw new ServiceException("ResultIdentityMismatch","确认结果项目或版本不匹配，未保存。");access[id]=a with{AppliedRevision=p.Revision};await Save(ct);return new SelectionFinalResult(id,p.ConfirmedAtUtc,p.Items.Select(x=>new SelectionFinalItem(id,x.ImageId,x.OriginalFileName,x.Selected,x.Favorite,x.CustomerNote,x.ExtraSelected)).ToArray()){SelectionVersion=p.SelectionVersion,Revision=p.Revision,IsLocked=p.IsLocked};},ct);
 public Task<OnlineSelectionProviderResult<bool>> UnpublishAsync(Guid id,CancellationToken ct=default)=>Run(async()=>{var a=AccessFor(id);using var r=Request(HttpMethod.Post,$"/v1/selection-projects/{id}/unpublish",a.OwnerToken);await Parse<bool>(await client.SendAsync(r,ct),ct);access[id]=a with{Link=null};await Save(ct);return true;},ct);
 public Task<OnlineSelectionProviderResult<bool>> DeleteCloudAssetAsync(Guid id,Guid asset,CancellationToken ct=default)=>Run(async()=>{var a=AccessFor(id);using var r=Request(HttpMethod.Delete,$"/v1/selection-projects/{id}/assets/{asset}/cloud-copy",a.OwnerToken);return await Parse<bool>(await client.SendAsync(r,ct),ct);},ct);
 Access AccessFor(Guid id)=>access.TryGetValue(id,out var a)?a:throw new ServiceException("RemoteProjectMissing","请先同步创建此项目。");
 static SelectionProject Model(SelectionProjectResponse p)=>new(p.Id,p.PublicId,p.Name,p.ClientDisplayName??"",Enum.TryParse<SelectionProjectStatus>(p.Status,out var status)?status:SelectionProjectStatus.Draft,p.TargetCount,p.DeadlineUtc,null,DateTimeOffset.UtcNow,DateTimeOffset.UtcNow);
 public void Dispose(){client.Dispose();accessGate.Dispose();}
 // HTTP owns this wrapper; caller retains the proxy stream's lifetime.
 private sealed class BorrowedStream(Stream source):Stream{public override bool CanRead=>source.CanRead;public override bool CanSeek=>source.CanSeek;public override bool CanWrite=>false;public override long Length=>source.Length;public override long Position{get=>source.Position;set=>source.Position=value;}public override void Flush(){}public override int Read(byte[]b,int o,int n)=>source.Read(b,o,n);public override ValueTask<int> ReadAsync(Memory<byte>b,CancellationToken ct=default)=>source.ReadAsync(b,ct);public override long Seek(long o,SeekOrigin origin)=>source.Seek(o,origin);public override void SetLength(long n)=>throw new NotSupportedException();public override void Write(byte[]b,int o,int n)=>throw new NotSupportedException();protected override void Dispose(bool disposing){} }
}
